"""Conservative sleep signal interpretation and reversible memory salience policy.

Research implementation: HealthKit collection and runtime scheduling are separate.
"""
from dataclasses import dataclass, replace
from datetime import datetime, timedelta

ASLEEP = frozenset({'asleepCore', 'asleepDeep', 'asleepREM', 'asleepUnspecified'})

@dataclass(frozen=True)
class SleepSignal:
    stage: str
    observed_at: datetime

@dataclass(frozen=True)
class MemoryCandidate:
    memory_id: str
    salience: float
    protected: bool
    evidence_status: str

class SleepCycle:
    def __init__(self, max_signal_age=timedelta(minutes=20)):
        self.max_signal_age = max_signal_age

    def decide(self, signal, now):
        if signal is None:
            return 'unknown'
        if signal.observed_at.tzinfo is None or now.tzinfo is None:
            return 'unknown'
        age = now - signal.observed_at
        if age < timedelta(0) or age > self.max_signal_age:
            return 'unknown'
        if signal.stage in ASLEEP:
            return 'sleep'
        if signal.stage == 'awake':
            return 'wake'
        return 'unknown'

    def dream(self, observations):
        # Never represent synthetic association as evidence or autobiography.
        return {'status': 'unverified_hypothesis', 'autobiographical': False,
                'inputs': tuple(observations), 'requires_review': True}

    def degrade(self, candidate, inactive_days):
        if inactive_days < 0:
            raise ValueError('inactive_days cannot be negative')
        if candidate.protected or candidate.evidence_status in ('verified', 'disputed'):
            return candidate
        return replace(candidate, salience=max(0.1, candidate.salience * (0.98 ** inactive_days)))
EOF
